; ============================================================
; Bank $DE: the data the code source does not emit
;
; Generated by tools/extract_data.py from symbols/data_survey.csv;
; do not edit (run `python3 tools/extract_data.py generate`). Each
; piece is a row of the survey (its kind, format, readers and
; confidence are there) at its address. fill and pointer tables are
; source; incbin reads an asset that tools/extract_data.py writes
; from your own ROM to build/assets/, a pack tools/build_rom.py
; makes from one in build/packs/ (event scripts assembled from
; their disassembly first), text or records it encodes into
; build/text/ and build/records/, or battle scripts it assembles
; into build/battle/ (symbols/data_assets.csv lists them; nothing
; here is ROM data).
; ============================================================

; $DE:0000-$DE:BFFF (49,152 B), sprite_layout, confirmed: per sprite set: frame records of
; sprite tiles (tile, attributes, offsets)
; Read by Battle_InitScene (BattleRom_SprFramesPtr), Evt_LoadSpriteRec / Spr_Load*
; (Field_E4Ptr1), Menu_SprLoad (MenuRom_E4FramePtrs).
org $DE0000
SprLayout_DE0000:
    incbin "../../build/assets/sprite_layout/SprLayout_DE0000.bin"

; $DE:C000-$DE:E2B0 (8,881 B), text, confirmed: u16 string pointers (same bank), then strings:
; $A0-$FF glyphs, $21-$9F dictionary, $00-$20 codes, $00 ends
; Read by Evt_OpB8_SetMsgPtr (table), Evt_OpBB_Msg / Evt_OpC0_MsgChoice ..., TextWin_Init,
; TextWin_State0 (decode).
org $DEC000
MsgTable_DEC000:
    incbin "../../build/text/MsgTable_DEC000.bin"          ; text unit Messages_DEC000 (strtable)

; $DE:E2B1-$DE:E2FF (79 B), padding, confirmed: 79 x $00
org $DEE2B1
Padding_DEE2B1:
    fillbyte $00
    fill 79

; $DE:E300-$DE:F96C (5,741 B), text, confirmed: u16 string pointers (same bank), then strings:
; $A0-$FF glyphs, $21-$9F dictionary, $00-$20 codes, $00 ends
; Read by Evt_OpB8_SetMsgPtr (table), Evt_OpBB_Msg / Evt_OpC0_MsgChoice ..., TextWin_Init,
; TextWin_State0 (decode).
org $DEE300
MsgTable_DEE300:
    incbin "../../build/text/MsgTable_DEE300.bin"          ; text unit Messages_DEE300 (strtable)

; $DE:F96D-$DE:F9FF (147 B), padding, confirmed: 147 x $00
org $DEF96D
Padding_DEF96D:
    fillbyte $00
    fill 147

; $DE:FA00-$DE:FAFD (254 B), text, confirmed: 127 u16 pointers (bank $DE) to dictionary
; sub-strings
; Read by TextWin_State0_Draw, TextWin_CodeExt.
org $DEFA00
TextWin_DictPtrs:
    incbin "../../build/text/TextWin_DictPtrs.bin"          ; text unit Dictionary (ptrs ptr)

; $DE:FAFE-$DE:FAFF (2 B), table, probable: 1 u16 (a 128th dictionary pointer)
; Read by TextWin_CodeExt (only).
org $DEFAFE
Table_DEFAFE:
    incbin "../../build/text/Table_DEFAFE.bin"          ; text unit Dictionary (ptrs ptr128)

; $DE:FB00-$DE:FD00 (513 B), text, confirmed: dictionary sub-strings: length byte, then glyph
; bytes
; Read by TextWin_State0_Draw, TextWin_State1.
org $DEFB00
Text_DEFB00:
    incbin "../../build/text/Text_DEFB00.bin"          ; text unit Dictionary (dict)

; $DE:FD01-$DE:FEFF (511 B), padding, confirmed: 511 x $00
org $DEFD01
Padding_DEFD01:
    fillbyte $00
    fill 511

; $DE:FF00-$DE:FF52 (83 B), text, confirmed: u16 string pointers (same bank), then strings:
; $A0-$FF glyphs, $21-$9F dictionary, $00-$20 codes, $00 ends
; Read by Field_Unk*: the treasure message (bankC0 TextWin setup), TextWin_State0.
org $DEFF00
Text_DEFF00:
    incbin "../../build/text/Text_DEFF00.bin"          ; text unit TreasureMessages (strtable)

; $DE:FF53-$DE:FFFF (173 B), padding, confirmed: 173 x $00
org $DEFF53
Padding_DEFF53:
    fillbyte $00
    fill 173
